-- Noor Ilm Prompt 5 dashboard reference migration for future Supabase PostgreSQL.
-- Documentation only in demo mode; no production migration is executed here.

create table if not exists public.learner_requirements (id uuid primary key default gen_random_uuid(), learner_id uuid not null references auth.users(id) on delete cascade, subject text not null, level text, learning_goal text, preferred_languages text[] default '{}', timezone text, preferred_schedule text, budget_range text, status text not null default 'draft' check (status in ('draft','open','reviewing','closed')), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.requirement_responses (id uuid primary key default gen_random_uuid(), requirement_id uuid not null references public.learner_requirements(id) on delete cascade, instructor_id uuid not null references auth.users(id) on delete cascade, message text, status text not null default 'submitted' check (status in ('submitted','accepted','rejected','withdrawn')), created_at timestamptz not null default now(), unique(requirement_id, instructor_id));
create table if not exists public.instructor_availability (id uuid primary key default gen_random_uuid(), instructor_id uuid not null references auth.users(id) on delete cascade, weekday smallint not null check (weekday between 0 and 6), start_time time not null, end_time time not null, timezone text not null, active boolean not null default true, created_at timestamptz not null default now(), check (end_time > start_time));
create table if not exists public.trial_requests (id uuid primary key default gen_random_uuid(), learner_id uuid not null references auth.users(id) on delete cascade, instructor_id uuid not null references auth.users(id) on delete cascade, course_id uuid, proposed_start timestamptz, timezone text, status text not null default 'requested' check (status in ('requested','proposed','accepted','rejected','cancelled')), created_at timestamptz not null default now());
create table if not exists public.class_sessions (id uuid primary key default gen_random_uuid(), learner_id uuid not null references auth.users(id) on delete cascade, instructor_id uuid not null references auth.users(id) on delete cascade, trial_request_id uuid references public.trial_requests(id), starts_at timestamptz, ends_at timestamptz, timezone text, status text not null default 'scheduled' check (status in ('scheduled','completed','cancelled','no_show')), created_at timestamptz not null default now());
create table if not exists public.enrolments (id uuid primary key default gen_random_uuid(), learner_id uuid not null references auth.users(id) on delete cascade, course_id uuid not null, instructor_id uuid references auth.users(id), status text not null default 'active' check (status in ('active','paused','completed','cancelled')), created_at timestamptz not null default now());
create table if not exists public.lesson_progress (id uuid primary key default gen_random_uuid(), enrolment_id uuid not null references public.enrolments(id) on delete cascade, lesson_id uuid not null, completed_at timestamptz, unique(enrolment_id, lesson_id));
create table if not exists public.training_records (id uuid primary key default gen_random_uuid(), instructor_id uuid not null references auth.users(id) on delete cascade, training_status text not null default 'not_started', test_status text not null default 'not_started', reviewed_by uuid references auth.users(id), updated_at timestamptz not null default now(), check (reviewed_by is null or reviewed_by <> instructor_id));
create table if not exists public.instructor_student_relationships (id uuid primary key default gen_random_uuid(), instructor_id uuid not null references auth.users(id) on delete cascade, learner_id uuid not null references auth.users(id) on delete cascade, status text not null default 'active' check (status in ('pending','active','ended')), created_at timestamptz not null default now(), unique(instructor_id, learner_id));
create table if not exists public.session_ledger (id uuid primary key default gen_random_uuid(), session_id uuid not null references public.class_sessions(id) on delete cascade, instructor_id uuid not null references auth.users(id) on delete cascade, hours numeric(8,2), hourly_rate numeric(10,2), platform_fee numeric(10,2), status text not null default 'pending' check (status in ('pending','approved','void')), created_at timestamptz not null default now());
create table if not exists public.notifications (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, kind text not null, title text not null, body text, read_at timestamptz, created_at timestamptz not null default now());
create table if not exists public.conversations (id uuid primary key default gen_random_uuid(), created_at timestamptz not null default now());
create table if not exists public.conversation_participants (conversation_id uuid not null references public.conversations(id) on delete cascade, user_id uuid not null references auth.users(id) on delete cascade, primary key(conversation_id, user_id));
create table if not exists public.messages (id uuid primary key default gen_random_uuid(), conversation_id uuid not null references public.conversations(id) on delete cascade, sender_id uuid not null references auth.users(id) on delete cascade, body text not null, created_at timestamptz not null default now());

-- RLS design: owners can read/write their own learner rows; instructors can read only open requirements;
-- participants can read bookings/conversations; students are relationship-scoped; ledger/training approval is server/admin-only.
-- Every policy should be paired with server-side role and ownership checks in RPC procedures.
